declare a intelligence_control.edge_authorities%rowtype;t intelligence_control.edge_ticks%rowtype;
 s intelligence_control.integration_subscriptions%rowtype;f analytics.pipeline_forecasts%rowtype;
 existing intelligence_control.edge_receiver_receipts%rowtype;v jsonb;b bytea;secret_value text;secret_id uuid;
 saved_claims text;source_tenant uuid;tick_id uuid;begin
 perform intelligence_control.runtime_worker_required(p_runtime_id);
 if p_payload is null or jsonb_typeof(p_payload)<>'object' then raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
 select * into a from intelligence_control.edge_authorities where runtime_id=p_runtime_id and enabled
 and issued_at<=statement_timestamp() and expires_at>statement_timestamp() for update;
 if not found then raise exception using errcode='42501',message='RUNTIME_SCOPE_DENIED';end if;
 if p_action='begin_tick' then
 if (p_payload-array['tickId','kind','secretHash'])<>'{}' or not(p_payload ?& array['tickId','kind','secretHash'])
 or p_payload->>'kind' not in('delivery','subscription','health') or p_payload->>'secretHash' is distinct from a.schedule_secret_hash then
 raise exception using errcode='42501',message='WORKER_ACCESS_DENIED';end if;
 tick_id:=(p_payload->>'tickId')::uuid;
 if tick_id is null then raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
 if exists(select 1 from intelligence_control.edge_ticks where runtime_id=p_runtime_id and id=tick_id) then
 return jsonb_build_object('permitted',false);end if;
 update intelligence_control.edge_ticks set state='unknown' where runtime_id=p_runtime_id and kind=p_payload->>'kind' and state='running' and lease_until<=statement_timestamp();
 if exists(select 1 from intelligence_control.edge_ticks where runtime_id=p_runtime_id and kind=p_payload->>'kind' and state='running') then
 return jsonb_build_object('permitted',false);end if;
 select tenant_id into source_tenant from intelligence_control.runtime_worker_scopes
 where runtime_id=p_runtime_id and intelligence_control.runtime_scope_allowed(p_runtime_id,tenant_id,legal_entity_id,branch_id) limit 1;
 insert into intelligence_control.edge_ticks(runtime_id,id,kind,state,lease_until)
 values(p_runtime_id,tick_id,p_payload->>'kind','running',statement_timestamp()+interval '90 seconds');
 return jsonb_build_object('permitted',true,'tenantId',source_tenant);
 elsif p_action='finish_tick' then
 if (p_payload-array['tickId','success','summary'])<>'{}' or not(p_payload ?& array['tickId','success','summary'])
 or jsonb_typeof(p_payload->'success')<>'boolean' or jsonb_typeof(p_payload->'summary')<>'object'
 or octet_length((p_payload->'summary')::text)>2048 then raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
 select * into t from intelligence_control.edge_ticks where runtime_id=p_runtime_id and id=(p_payload->>'tickId')::uuid for update;
 if t.id is null or t.state<>'running' or t.lease_until<=statement_timestamp() then raise exception using errcode='42501',message='LEASE_UNAVAILABLE';end if;
 insert into intelligence_control.edge_tick_outcomes values(p_runtime_id,t.id,(p_payload->>'success')::boolean,p_payload->'summary',statement_timestamp());
 update intelligence_control.edge_ticks set state=case when (p_payload->>'success')::boolean then 'completed' else 'failed' end where runtime_id=p_runtime_id and id=t.id;
 return jsonb_build_object('recorded',true);
 elsif p_action='key' then
 if (p_payload-'ref')<>'{}' or not(p_payload ? 'ref') then raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
 select k.secret_id into secret_id from intelligence_control.edge_key_refs k where k.runtime_id=p_runtime_id and k.ref=p_payload->>'ref';
 if secret_id is null then raise exception using errcode='42501',message='DELIVERY_KEY_UNAVAILABLE';end if;
 -- Only this runtime's two explicitly provisioned Vault IDs can be read. No
 -- caller-provided Vault ID/name and no existing project secret are discoverable.
 select decrypted_secret into secret_value from vault.decrypted_secrets where id=secret_id;
 if secret_value is null or secret_value !~ '^[a-f0-9]{64}$' then raise exception using errcode='55000',message='DELIVERY_KEY_UNAVAILABLE';end if;
 return jsonb_build_object('value',secret_value);
 elsif p_action in('receive','receive_probe') then
 if (p_payload-array['event','keyVersion','payloadBase64','sha256','timestamp','mode'])<>'{}'
 or not(p_payload ?& array['event','keyVersion','payloadBase64','sha256','timestamp','mode'])
 or p_payload->>'mode' not in('accept','redirect','timeout','reject')
 or (p_action='receive') is distinct from (p_payload->>'mode' in('accept','timeout')) then
 raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
 v:=p_payload->'event';b:=decode(p_payload->>'payloadBase64','base64');
 if octet_length(b)>8192 or convert_from(b,'UTF8')::jsonb is distinct from v
 or encode(extensions.digest(b,'sha256'),'hex') is distinct from p_payload->>'sha256'
 or (p_payload->>'timestamp')::bigint<extract(epoch from statement_timestamp())-300
 or (p_payload->>'timestamp')::bigint>extract(epoch from statement_timestamp())+30 then
 raise exception using errcode='22023',message='EVENT_CONTRACT_MISMATCH';end if;
 select s0.* into s from intelligence_control.integration_subscriptions s0
 where s0.id=case p_payload->>'mode'
 when 'accept' then '58699e8a-28fd-4356-8cad-87ce46e17ddd'::uuid
 when 'redirect' then '2bdbd842-5b94-464b-85fc-22d722498831'::uuid
 when 'timeout' then '0961e194-dc0b-4632-8c2d-65686fc9f111'::uuid
 when 'reject' then '360e7a9d-08a5-4349-854f-c2343ce2ff5d'::uuid end
 and s0.enabled and s0.key_version=(p_payload->>'keyVersion')::integer
 and s0.key_ref='w5/runtime/20261008/delivery/v'||(p_payload->>'keyVersion')
 and s0.url='https://xpdoufauvrbdmxgngetv.supabase.co/functions/v1/wave5-receiver/'||(p_payload->>'mode')
 and intelligence_control.runtime_scope_allowed(p_runtime_id,s0.tenant_id,s0.legal_entity_id,s0.branch_id);
 if not found then raise exception using errcode='42501',message='INTEGRATION_ACCESS_DENIED';end if;
 select f0.* into f from core.outbox_events o join analytics.pipeline_forecasts f0 on f0.tenant_id=o.tenant_id and f0.id=o.aggregate_id
 where o.id=(v->>'eventId')::uuid and o.tenant_id=s.tenant_id and o.topic='analytics.freeze_pipeline' and o.aggregate_type='pipeline_forecast'
 and f0.legal_entity_id=s.legal_entity_id and f0.branch_id=s.branch_id;
 if f.id is null or v is distinct from jsonb_build_object('eventId',(v->>'eventId')::uuid,'type','analytics.forecast.frozen.v1',
 'tenantId',s.tenant_id,'legalEntityId',s.legal_entity_id,'branchId',s.branch_id,'forecastId',f.id,'definitionVersion',1,'sourceHash',f.source_hash) then
 raise exception using errcode='42501',message='EVENT_CONTRACT_MISMATCH';end if;
 perform intelligence_control.quota_limit(s.tenant_id,'webhook.deliveries');
 saved_claims:=current_setting('request.jwt.claims',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',s.created_by,'role','authenticated','aal','aal1')::text,true);
 perform core.wave3_require_scope(s.tenant_id,'integrations.manage',s.legal_entity_id,s.branch_id);
 perform api.get_pipeline_forecast(s.tenant_id,s.legal_entity_id,s.branch_id,f.id);
 perform set_config('request.jwt.claims',coalesce(saved_claims,''),true);
 if p_action='receive_probe' then return jsonb_build_object('permitted',true);end if;
 select * into existing from intelligence_control.edge_receiver_receipts where runtime_id=p_runtime_id and subscription_id=s.id and event_id=(v->>'eventId')::uuid;
 if found then
 if existing.payload<>b or existing.sha256<>p_payload->>'sha256' then raise exception using errcode='23505',message='RECEIVER_DIGEST_CONFLICT';end if;
 return jsonb_build_object('acknowledged',true,'duplicate',true,'sha256',existing.sha256);end if;
 if not exists(select 1 from intelligence_control.delivery_heads d join intelligence_control.delivery_attempts da
 on da.tenant_id=d.tenant_id and da.delivery_id=d.id and da.attempt=d.attempt and da.lease_id=d.lease_id
 where d.tenant_id=s.tenant_id and d.subscription_id=s.id and d.event_id=(v->>'eventId')::uuid
 and d.state='leased' and d.lease_until>statement_timestamp() and da.key_version=s.key_version and da.subscription_version=s.version) then
 raise exception using errcode='42501',message='LEASE_UNAVAILABLE';end if;
 insert into intelligence_control.edge_receiver_receipts values(p_runtime_id,(v->>'eventId')::uuid,s.tenant_id,s.legal_entity_id,s.branch_id,s.id,
 (p_payload->>'keyVersion')::integer,b,p_payload->>'sha256',(p_payload->>'timestamp')::bigint,statement_timestamp());
 return jsonb_build_object('acknowledged',true,'duplicate',false,'sha256',p_payload->>'sha256');
 end if;
 raise exception using errcode='22023',message='WORKER_ACTION_INVALID';
end

declare q numeric;cap numeric;bucket intelligence_control.quota_periods%rowtype;r intelligence_control.usage_reservations%rowtype;begin
 perform intelligence_control.worker_required();
 if p_tenant_id is null or p_invocation_id is null or p_metric_code is null or p_metric_code not in('ai.tokens','webhook.deliveries') or p_quantity is null
 or p_quantity !~ '^[1-9][0-9]{0,19}$' or p_period_start is null or p_period_end is null
 or not isfinite(p_period_start) or not isfinite(p_period_end) or p_period_start>=p_period_end
 or p_period_end-p_period_start>interval '366 days' or statement_timestamp()<p_period_start or statement_timestamp()>=p_period_end then
 raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
 -- Share the billing lock with synthetic plan activation and seat admission.
 perform 1 from billing.tenant_subscriptions where tenant_id=p_tenant_id for update;
 q:=p_quantity::numeric;cap:=intelligence_control.quota_limit(p_tenant_id,p_metric_code);
 if not exists(select 1 from billing.tenant_subscriptions s where s.tenant_id=p_tenant_id and
 ((s.status='trialing' and p_period_start=coalesce(s.trial_started_at,s.created_at) and p_period_end=s.trial_ends_at)
 or (s.status='active' and p_period_end=s.current_period_ends_at))) then
 raise exception using errcode='22023',message='PERIOD_CONFLICT';end if;
 -- Serialize the tenant/metric before choosing the period: overlapping caller-
 -- supplied windows cannot split one allowance into multiple hard-cap buckets.
 perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||p_metric_code,5));
 if exists(select 1 from intelligence_control.quota_periods where tenant_id=p_tenant_id and metric_code=p_metric_code
 and period_start<>p_period_start and period_start<p_period_end and period_end>p_period_start) then
 raise exception using errcode='22023',message='PERIOD_CONFLICT';end if;
 insert into intelligence_control.quota_periods(tenant_id,metric_code,period_start,period_end)
 values(p_tenant_id,p_metric_code,p_period_start,p_period_end) on conflict do nothing;
 select * into bucket from intelligence_control.quota_periods where tenant_id=p_tenant_id and metric_code=p_metric_code
 and period_start=p_period_start for update;
 if bucket.period_end<>p_period_end then raise exception using errcode='22023',message='PERIOD_CONFLICT';end if;
 select * into r from intelligence_control.usage_reservations where tenant_id=p_tenant_id and invocation_id=p_invocation_id;
 if found then
 if r.metric_code<>p_metric_code or r.period_start<>p_period_start or r.reserved_units<>q then
 raise exception using errcode='22023',message='IDEMPOTENCY_MISMATCH';end if;
 return jsonb_build_object('invocationId',r.invocation_id,'reservedUnits',r.reserved_units::text);
 end if;
 if bucket.settled_units+bucket.reserved_units+q>cap then raise exception using errcode='54000',message='QUOTA_EXCEEDED';end if;
 insert into intelligence_control.usage_reservations values(p_tenant_id,p_invocation_id,p_metric_code,p_period_start,q,statement_timestamp());
 update intelligence_control.quota_periods set reserved_units=reserved_units+q where tenant_id=p_tenant_id and metric_code=p_metric_code and period_start=p_period_start;
 return jsonb_build_object('invocationId',p_invocation_id,'reservedUnits',q::text);
end

declare d intelligence_control.delivery_heads%rowtype;s intelligence_control.integration_subscriptions%rowtype;
 o intelligence_control.delivery_outcomes%rowtype;subscription billing.tenant_subscriptions%rowtype;v_state text;status integer;begin
 perform intelligence_control.runtime_worker_required(p_runtime_id);
 if p_action not in('readiness','claim','settle_acknowledged') and not exists(
 select 1 from intelligence_control.delivery_heads h join intelligence_control.integration_subscriptions s0
 on s0.tenant_id=h.tenant_id and s0.id=h.subscription_id
 where h.id=(p_payload->>'deliveryId')::uuid
 and intelligence_control.runtime_scope_allowed(p_runtime_id,s0.tenant_id,s0.legal_entity_id,s0.branch_id)) then
 raise exception using errcode='42501',message='RUNTIME_SCOPE_DENIED';end if;
 if p_action='readiness' then return jsonb_build_object('contractRevision',1,'ready',true,'providers',jsonb_build_object('committed_webhook.v1',1,'synthetic_subscription.v1',1));end if;
 if p_action='claim' then
 -- A lease lost after send cannot be auto-retried. ACK rows can be reconciled
 -- separately; expired attempts with no outcome retain uncertain reservations.
 update intelligence_control.delivery_heads set state='unknown' where state='leased' and lease_until<=statement_timestamp()
 and exists(select 1 from intelligence_control.integration_subscriptions s0
 where s0.id=subscription_id and s0.tenant_id=delivery_heads.tenant_id
 and intelligence_control.runtime_scope_allowed(p_runtime_id,s0.tenant_id,s0.legal_entity_id,s0.branch_id));
 insert into intelligence_control.delivery_heads(tenant_id,subscription_id,event_id)
 select s0.tenant_id,s0.id,e.id from intelligence_control.integration_subscriptions s0
 join analytics.pipeline_forecasts f on f.tenant_id=s0.tenant_id and f.legal_entity_id=s0.legal_entity_id and f.branch_id is not distinct from s0.branch_id
 join core.outbox_events e on e.tenant_id=f.tenant_id and e.aggregate_id=f.id and e.aggregate_type='pipeline_forecast' and e.topic='analytics.freeze_pipeline'
 where s0.enabled and intelligence_control.runtime_scope_allowed(p_runtime_id,s0.tenant_id,s0.legal_entity_id,s0.branch_id)
 and e.created_at>=s0.created_at and not exists(select 1 from intelligence_control.delivery_heads h
 where h.tenant_id=s0.tenant_id and h.subscription_id=s0.id and h.event_id=e.id and h.generation=0)
 order by e.created_at,e.id limit 1000 on conflict do nothing;
 select h.* into d from intelligence_control.delivery_heads h where
 exists(select 1 from intelligence_control.integration_subscriptions s0 where s0.tenant_id=h.tenant_id and s0.id=h.subscription_id
 and intelligence_control.runtime_scope_allowed(p_runtime_id,s0.tenant_id,s0.legal_entity_id,s0.branch_id))
 and state in('pending','retry') and available_at<=statement_timestamp()
 and attempt<8 order by available_at,id for update skip locked limit 1;
 if not found then return null;end if;
 select * into s from intelligence_control.integration_subscriptions where tenant_id=d.tenant_id and id=d.subscription_id and enabled;
 if not found then update intelligence_control.delivery_heads set state='dead_letter' where id=d.id;return null;end if;
 select * into subscription from billing.tenant_subscriptions where tenant_id=d.tenant_id;
 if d.period_start is null then
 d.period_start:=case when subscription.status='trialing' then coalesce(subscription.trial_started_at,subscription.created_at)
 else coalesce((select period_start from intelligence_control.quota_periods where tenant_id=d.tenant_id and metric_code='webhook.deliveries'
 and period_end=subscription.current_period_ends_at limit 1),date_trunc('month',statement_timestamp())) end;
 d.period_end:=case when subscription.status='trialing' then subscription.trial_ends_at else subscription.current_period_ends_at end;
 end if;
 if d.period_end is null then raise exception using errcode='55000',message='BILLING_PERIOD_UNAVAILABLE';end if;
 update intelligence_control.delivery_heads set attempt=attempt+1,state='leased',lease_id=gen_random_uuid(),lease_until=statement_timestamp()+interval '60 seconds',
 period_start=d.period_start,period_end=d.period_end where id=d.id returning * into d;
 insert into intelligence_control.delivery_attempts values(d.tenant_id,d.id,d.attempt,d.lease_id,s.key_version,s.version,statement_timestamp());
 begin
 return intelligence_control.delivery_authorize(d.id,d.lease_id);
 exception when insufficient_privilege then
 -- No send occurred. Keep this denied item from starving another tenant's
 -- queue; replay still requires a reasoned MFA review after access is fixed.
 update intelligence_control.delivery_heads set state='dead_letter' where id=d.id;
 return null;
 end;
 end if;
 if p_action='authorize' then return intelligence_control.delivery_authorize((p_payload->>'deliveryId')::uuid,(p_payload->>'leaseId')::uuid);end if;
 if p_action='key_ref' then
 perform intelligence_control.delivery_authorize((p_payload->>'deliveryId')::uuid,(p_payload->>'leaseId')::uuid);
 return to_jsonb((select s0.key_ref from intelligence_control.delivery_heads d0 join intelligence_control.integration_subscriptions s0 on s0.tenant_id=d0.tenant_id and s0.id=d0.subscription_id where d0.id=(p_payload->>'deliveryId')::uuid));
 end if;
 if p_action='outcome' then
 select * into d from intelligence_control.delivery_heads where id=(p_payload->>'deliveryId')::uuid and lease_id=(p_payload->>'leaseId')::uuid for update;
 if not found then raise exception using errcode='42501',message='LEASE_UNAVAILABLE';end if;
 v_state:=p_payload->>'state';status:=(p_payload->>'httpStatus')::integer;
 if v_state not in('acknowledged','retry','unknown','dead_letter') or v_state is null
 or (v_state='acknowledged' and (status is null or status not between 200 and 299))
 or (v_state='unknown' and status is not null) or (v_state in('retry','dead_letter') and (status is null or status between 200 and 299))
 or (v_state='retry' and d.attempt>=8) or (v_state='dead_letter' and d.attempt<>8) then
 raise exception using errcode='22023',message='OUTCOME_MISMATCH';end if;
 select * into o from intelligence_control.delivery_outcomes where tenant_id=d.tenant_id and delivery_id=d.id and attempt=d.attempt;
 if found then
 if o.state<>v_state or o.http_status is distinct from status then raise exception using errcode='22023',message='IDEMPOTENCY_MISMATCH';end if;return '{}'::jsonb;
 end if;
 insert into intelligence_control.delivery_outcomes values(d.tenant_id,d.id,d.attempt,v_state,status,statement_timestamp());
 update intelligence_control.delivery_heads set state=v_state,available_at=statement_timestamp()+make_interval(secs=>least(3600,15*power(2,d.attempt-1)::integer)) where id=d.id;
 return '{}'::jsonb;
 end if;
 if p_action='settle_acknowledged' then
 for d in select * from intelligence_control.delivery_heads h where h.state='acknowledged' and exists(
 select 1 from intelligence_control.integration_subscriptions s0 where s0.tenant_id=h.tenant_id and s0.id=h.subscription_id
 and intelligence_control.runtime_scope_allowed(p_runtime_id,s0.tenant_id,s0.legal_entity_id,s0.branch_id))
 and not exists(select 1 from intelligence_control.usage_events u where u.tenant_id=h.tenant_id and u.invocation_id=h.invocation_id)
 order by h.id for update skip locked limit 100 loop
 perform api.wave5_settle_usage(d.tenant_id,d.invocation_id,d.usage_event_id,'1');
 end loop;return '{}'::jsonb;
 end if;
 raise exception using errcode='22023',message='VALIDATION_ERROR';
end

declare tenant uuid;entity uuid;branch uuid;s jsonb;rows jsonb;n integer;cursor uuid;begin
 perform intelligence_control.runtime_worker_required(p_runtime_id);
 if p_payload is null or jsonb_typeof(p_payload)<>'object' then raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
 if p_action like 'delivery.%' then
 return api.wave5_runtime_delivery_worker(p_runtime_id,substring(p_action from 10),p_payload);end if;
 if p_action='model.readiness' then return api.wave5_model_worker('readiness',p_payload);end if;
 if p_action like 'external.%' then
 select tenant_id,legal_entity_id,branch_id into tenant,entity,branch from intelligence_control.integration_credentials
 where token_hash=p_payload->>'tokenHash';
 elsif p_action='model.begin' then
 select f.tenant_id,f.legal_entity_id,f.branch_id into tenant,entity,branch from analytics.pipeline_forecasts f
 where f.tenant_id=(p_payload->>'tenantId')::uuid and f.id=(p_payload->>'sourceId')::uuid;
 elsif p_action='model.outcome' then
 select f.tenant_id,f.legal_entity_id,f.branch_id into tenant,entity,branch from intelligence_control.model_invocations i
 join analytics.pipeline_forecasts f on f.tenant_id=i.tenant_id and f.id=i.source_id
 where i.invocation_id=(p_payload->>'invocationId')::uuid;
 elsif p_action='entitlement' then
 s:=p_payload->'scope';tenant:=(s->>'tenantId')::uuid;entity:=(s->>'legalEntityId')::uuid;branch:=(s->>'branchId')::uuid;
 elsif p_action in('usage.reserve','usage.settle','subscription.apply','health.collect') then
 tenant:=(p_payload->>'tenantId')::uuid;
 if not intelligence_control.runtime_tenant_allowed(p_runtime_id,tenant) then
 raise exception using errcode='42501',message='RUNTIME_SCOPE_DENIED';end if;
 if p_action='usage.reserve' then return api.wave5_reserve_usage(tenant,(p_payload->>'invocationId')::uuid,p_payload->>'metric',
 (p_payload->>'periodStart')::timestamptz,(p_payload->>'periodEnd')::timestamptz,p_payload->>'quantity');end if;
 if p_action='usage.settle' then return api.wave5_settle_usage(tenant,(p_payload->>'invocationId')::uuid,(p_payload->>'eventId')::uuid,p_payload->>'quantity');end if;
 if p_action='subscription.apply' then return api.apply_synthetic_subscription(tenant,(p_payload->>'revisionId')::uuid);end if;
 return api.wave5_health_collect((p_payload->>'collectionId')::uuid,tenant);
 elsif p_action='subscription.due' then
 select coalesce(jsonb_agg(jsonb_build_object('tenantId',tenant_id,'revisionId',id) order by id),'[]'),count(*) into rows,n
 from(select r.id,r.tenant_id from intelligence_control.subscription_revisions r
 join intelligence_control.synthetic_tenants t on t.tenant_id=r.tenant_id and t.allowed
 where intelligence_control.runtime_tenant_allowed(p_runtime_id,r.tenant_id)
 and r.trial_starts_at<=statement_timestamp() and r.trial_ends_at>statement_timestamp()
 and (p_payload->>'after' is null or r.id>(p_payload->>'after')::uuid)
 and not exists(select 1 from intelligence_control.subscription_activations a where a.tenant_id=r.tenant_id and a.revision_id=r.id)
 order by r.id limit 51) q;
 if n>50 then cursor:=(rows->49->>'revisionId')::uuid;rows:=rows-50;end if;
 return jsonb_build_object('contractRevision',1,'items',rows,'nextCursor',cursor);
 else raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
 if not intelligence_control.runtime_scope_allowed(p_runtime_id,tenant,entity,branch) then
 raise exception using errcode='42501',message='RUNTIME_SCOPE_DENIED';end if;
 if p_action in('external.credential','external.reserve','external.dispatch') then
 return api.wave5_external_worker(substring(p_action from 10),p_payload);end if;
 if p_action='model.begin' then
 perform pg_advisory_xact_lock(hashtextextended(tenant::text||':wave5-runtime-model-budget',531));
 if not exists(select 1 from intelligence_control.model_invocations where invocation_id=(p_payload->>'invocationId')::uuid)
 and (select count(*) from intelligence_control.model_invocations where tenant_id=tenant)>=4 then
 raise exception using errcode='54000',message='MODEL_CALL_LIMIT';end if;
 if coalesce(p_payload->>'maxTokens','')!~ '^[1-9][0-9]{0,3}$' or (p_payload->>'maxTokens')::numeric>2000 then
 raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
 end if;
 if p_action in('model.begin','model.outcome') then return api.wave5_model_worker(substring(p_action from 7),p_payload);end if;
 if p_action='entitlement' then return to_jsonb(api.wave5_worker_entitlement(s));end if;
 raise exception using errcode='22023',message='VALIDATION_ERROR';
end

declare q numeric;r intelligence_control.usage_reservations%rowtype;u intelligence_control.usage_events%rowtype;begin
 perform intelligence_control.worker_required();
 if p_quantity is null or p_quantity !~ '^(0|[1-9][0-9]{0,19})$' or p_event_id is null then raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
 q:=p_quantity::numeric;
 select * into r from intelligence_control.usage_reservations where tenant_id=p_tenant_id and invocation_id=p_invocation_id;
 if not found then raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||r.metric_code,5));
 perform 1 from intelligence_control.quota_periods where tenant_id=r.tenant_id and metric_code=r.metric_code and period_start=r.period_start for update;
 select * into u from intelligence_control.usage_events where tenant_id=p_tenant_id and invocation_id=p_invocation_id;
 if found then
 if u.event_id<>p_event_id or u.quantity<>q then raise exception using errcode='22023',message='IDEMPOTENCY_MISMATCH';end if;
 return jsonb_build_object('eventId',u.event_id,'quantity',u.quantity::text);
 end if;
 if q>r.reserved_units then raise exception using errcode='54000',message='RESERVATION_EXCEEDED';end if;
 insert into intelligence_control.usage_events values(p_tenant_id,p_invocation_id,p_event_id,q,statement_timestamp());
 update intelligence_control.quota_periods set reserved_units=reserved_units-r.reserved_units,settled_units=settled_units+q
 where tenant_id=r.tenant_id and metric_code=r.metric_code and period_start=r.period_start;
 return jsonb_build_object('eventId',p_event_id,'quantity',q::text);
end

declare d intelligence_control.delivery_heads%rowtype;s intelligence_control.integration_subscriptions%rowtype;
 f analytics.pipeline_forecasts%rowtype;a intelligence_control.delivery_attempts%rowtype;saved_claims text;begin
 select * into d from intelligence_control.delivery_heads where id=p_delivery_id and lease_id=p_lease_id and state='leased' and lease_until>statement_timestamp();
 if not found then raise exception using errcode='42501',message='LEASE_UNAVAILABLE';end if;
 select * into s from intelligence_control.integration_subscriptions where tenant_id=d.tenant_id and id=d.subscription_id and enabled;
 select * into a from intelligence_control.delivery_attempts where tenant_id=d.tenant_id and delivery_id=d.id and attempt=d.attempt;
 if s.id is null or a.lease_id is null or s.version<>a.subscription_version or s.key_version<>a.key_version then
 raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 perform intelligence_control.quota_limit(d.tenant_id,'webhook.deliveries');
 select f0.* into f from core.outbox_events o join analytics.pipeline_forecasts f0 on f0.tenant_id=o.tenant_id and f0.id=o.aggregate_id
 where o.id=d.event_id and o.tenant_id=s.tenant_id and o.topic='analytics.freeze_pipeline' and o.aggregate_type='pipeline_forecast'
 and f0.legal_entity_id=s.legal_entity_id and f0.branch_id is not distinct from s.branch_id;
 if not found then raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 -- Explicit subscription delegation uses AAL1. It never fabricates human MFA;
 -- the installed scope, role, entitlement and every captured-branch check run.
 saved_claims:=current_setting('request.jwt.claims',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',s.created_by,'role','authenticated','aal','aal1')::text,true);
 perform core.wave3_require_scope(s.tenant_id,'integrations.manage',s.legal_entity_id,s.branch_id);
 perform api.get_pipeline_forecast(s.tenant_id,s.legal_entity_id,s.branch_id,f.id);
 perform set_config('request.jwt.claims',coalesce(saved_claims,''),true);
 return jsonb_build_object('event',jsonb_build_object('eventId',d.event_id,'type','analytics.forecast.frozen.v1',
 'tenantId',s.tenant_id,'legalEntityId',s.legal_entity_id,'branchId',s.branch_id,'forecastId',f.id,'definitionVersion',1,'sourceHash',f.source_hash),
 'subscription',jsonb_build_object('id',s.id,'scope',jsonb_build_object('tenantId',s.tenant_id,'legalEntityId',s.legal_entity_id,'branchId',s.branch_id),
 'enabled',true,'url',s.url,'allowedHosts',jsonb_build_array(s.hostname),'keyVersion',s.key_version),
 'deliveryId',d.id,'leaseId',d.lease_id,'invocationId',d.invocation_id,'usageEventId',d.usage_event_id,
 'periodStart',analytics.process_utc(d.period_start),'periodEnd',analytics.process_utc(d.period_end),'attempt',d.attempt);
end

declare result numeric;begin
 select p.numeric_limit into result from billing.tenant_subscriptions s join billing.plan_entitlements p on p.plan_code=s.plan_code
 where s.tenant_id=t and p.entitlement_code='quota.'||metric and p.enabled
 and ((s.status='trialing' and coalesce(s.trial_started_at,s.created_at)<=statement_timestamp() and s.trial_ends_at>statement_timestamp()) or (s.status='active'
 and (s.current_period_ends_at is null or s.current_period_ends_at>statement_timestamp())));
 if result is null or result<0 or result<>trunc(result) or result>=100000000000000000000 then
 raise exception using errcode='42501',message='ENTITLEMENT_REQUIRED';end if;
 return result;
end

